<?php
namespace Tests\Feature;
use App\Models\{User,CentreManagerGrant as Grant,CentreManagerAccessRequest as Request};
use App\Support\{CentreManagerAccess as A,LearningAccess,TimetableGovernance};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Tests\Support\{AuditFault,CentreManagerFixture};
use Tests\TestCase;
class CentreManagerAccessTest extends TestCase {
 use LazilyRefreshDatabase,CentreManagerFixture;
 public function test_no_grants_are_seeded_and_timetable_manager_is_not_auto_promoted():void {$f=$this->f();TimetableGovernance::role($f['admin'],1,$f['manager'],0,1,'centre_manager',false,false,'Fictional timetable-only grant');$this->assertDatabaseCount('centre_manager_grants',0);$this->assertFalse(A::workspace($f['manager']));$this->assertFalse(LearningAccess::manager($f['manager']));}
 public function test_preview_and_preparation_do_not_grant_or_change_role():void {$f=$this->f();$r=$this->proposal($f);$this->assertTrue(A::intact($r));$this->assertFalse(A::workspace($f['manager']));$this->assertSame('manager',$f['manager']->fresh()->role);$this->assertDatabaseCount('centre_manager_grants',0);$this->assertStringNotContainsString('PRIVATE-ACCESS-REASON49',DB::table('centre_manager_access_requests')->value('details'));}
 public function test_independent_review_and_apply_activate_exact_groups_and_areas():void {$f=$this->f();$r=$this->proposal($f);A::review($f['checker'],1,$r,1,true,'Fictional independent review');$this->assertFalse(A::workspace($f['manager']));$g=A::apply($f['admin'],1,$r->fresh(),2);$this->assertTrue(A::intactGrant($g));$this->assertTrue(A::allows($f['manager'],$f['a'],'training'));$this->assertTrue(A::allows($f['manager'],$f['a'],'coordination'));$this->assertFalse(A::allows($f['manager'],$f['outside'],'training'));$this->assertFalse(A::allows($f['manager'],$f['a'],'reviews'));$this->assertFalse(LearningAccess::manager($f['manager']));}
 public function test_self_review_is_refused_and_explicit_ceo_override_is_audited():void {$f=$this->f();$r=$this->proposal($f);$this->reject(fn()=>A::review($f['admin'],1,$r,1,true,'Fictional self review',true));$ceo=User::factory()->create(['role'=>'ceo']);$f['admin']=$ceo;$r=$this->proposal($f);$this->reject(fn()=>A::review($ceo,1,$r,1,true,'Fictional implicit self review'));A::review($ceo,1,$r,1,true,'Fictional explicit CEO self review',true);$this->assertTrue($r->fresh()->approval['ceo_self_override']);$this->assertTrue(A::apply($ceo,1,$r->fresh(),2)->active);}
 public function test_rejection_retains_request_without_access():void {$f=$this->f();$r=$this->proposal($f);A::review($f['checker'],1,$r,1,false,'Fictional refused scope');$this->assertSame('Rejected',$r->fresh()->state);$this->assertFalse(A::workspace($f['manager']));$this->reject(fn()=>A::apply($f['admin'],1,$r->fresh(),2));}
 public function test_expiry_and_auth_version_changes_hold_access_immediately():void {$f=$this->f();$this->granted($f);$f['manager']->forceFill(['auth_version'=>2])->save();$this->assertFalse(A::workspace($f['manager']));$f['manager']->forceFill(['auth_version'=>1])->save();$this->travel(91)->days();$this->assertFalse(A::workspace($f['manager']));}
 public function test_revocation_is_immediate_and_old_apply_replay_cannot_restore_access():void {$f=$this->f();$r=$this->proposal($f);A::review($f['checker'],1,$r,1,true,'Fictional independent review');$g=A::apply($f['admin'],1,$r->fresh(),2);A::revoke($f['admin'],1,$f['manager'],$g->version,'Fictional immediate revocation');$this->assertFalse(A::workspace($f['manager']));$this->reject(fn()=>A::apply($f['admin'],1,$r->fresh(),2));$this->assertSame('manager',$f['manager']->fresh()->role);}
 public function test_group_identity_or_active_state_change_holds_whole_grant():void {$f=$this->f();$this->granted($f);$f['group']->forceFill(['active'=>false])->save();$this->assertFalse(A::workspace($f['manager']));}
 public function test_profile_move_enforces_current_membership_even_on_old_model():void {$f=$this->f();$this->granted($f);$old=clone$f['a'];$f['a']->update(['tutor_group_id'=>$f['otherGroup']->id]);$this->assertFalse(A::allows($f['manager'],$old,'training'));}
 public function test_changed_target_or_group_between_preview_and_prepare_is_refused():void {$f=$this->f();$v=A::preview($f['admin'],$f['manager'],[$f['group']->id],['training'],today()->addDays(90)->toDateString(),false);$f['group']->update(['name'=>'Changed group source']);$this->reject(fn()=>A::prepare($f['admin'],1,$f['manager'],[$f['group']->id],['training'],$v['expires'],false,$v['source_hash'],(string)Str::uuid(),'Fictional changed source'));}
 public function test_changed_reviewer_or_creator_authority_holds_activation():void {$f=$this->f();$r=$this->proposal($f);A::review($f['checker'],1,$r,1,true,'Fictional checked scope');$f['checker']->forceFill(['auth_version'=>2])->save();$this->reject(fn()=>A::apply($f['admin'],1,$r->fresh(),2));$this->assertFalse(A::workspace($f['manager']));}
 public function test_ceo_protection_prevents_subordinate_update_revoke_or_activation():void {$f=$this->f();$ceo=User::factory()->create(['role'=>'ceo']);$f['admin']=$ceo;$g=$this->granted($f,['training','coordination'],true);$this->reject(fn()=>A::revoke($f['checker'],1,$f['manager'],$g->version,'Fictional forbidden reversal'));$this->reject(fn()=>A::preview($f['checker'],$f['manager'],[$f['group']->id],['training'],today()->addDays(30)->toDateString(),false));A::revoke($ceo,1,$f['manager'],$g->version,'Fictional explicit CEO reversal');$this->assertFalse(A::workspace($f['manager']));}
 public function test_normal_admin_cannot_create_a_ceo_lock():void {$f=$this->f();$this->reject(fn()=>$this->proposal($f,['training'],null,true));}
 public function test_exact_activation_replay_does_not_duplicate_events():void {$f=$this->f();$r=$this->proposal($f);A::review($f['checker'],1,$r,1,true,'Fictional review');$g=A::apply($f['admin'],1,$r->fresh(),2);$before=DB::table('portal_operations_events')->count();$again=A::apply($f['admin'],1,$r->fresh(),2);$this->assertSame($g->details_hash,$again->details_hash);$this->assertSame($before,DB::table('portal_operations_events')->count());}
 public function test_exact_prepare_replay_returns_same_request_but_changed_reason_fails():void {$f=$this->f();$token=(string)Str::uuid();$a=$this->proposal($f,['training','coordination'],$token);$b=$this->proposal($f,['training','coordination'],$token);$this->assertSame($a->id,$b->id);$p=$a->details['preview'];$this->reject(fn()=>A::prepare($f['admin'],1,$f['manager'],$p['policy']['groups'],$p['areas'],$p['expires'],false,$p['source_hash'],$token,'Changed fictional request reason'));}
 public function test_replayed_request_cannot_be_activated_by_another_manager():void {$f=$this->f();$r=$this->proposal($f);A::review($f['checker'],1,$r,1,true,'Fictional review');A::apply($f['admin'],1,$r->fresh(),2);$this->reject(fn()=>A::apply($f['checker'],1,$r->fresh(),2));}
 public function test_corrupt_grant_or_request_is_not_silently_repaired():void {$f=$this->f();$g=$this->granted($f);DB::table('centre_manager_grants')->where('user_id',$g->user_id)->update(['active'=>false]);$this->assertFalse(A::workspace($f['manager']));$this->reject(fn()=>A::preview($f['admin'],$f['manager'],[$f['group']->id],['training'],today()->addDays(10)->toDateString(),false));}
 public function test_request_state_tamper_does_not_create_reviewed_access():void {$f=$this->f();$r=$this->proposal($f);DB::table('centre_manager_access_requests')->where('id',$r->id)->update(['state'=>'Approved','version'=>2]);$this->assertFalse(A::intact($r->fresh()));$this->reject(fn()=>A::apply($f['admin'],1,$r->fresh(),2));}
 public function test_activation_audit_failure_rolls_back_grant_and_request_state():void {$f=$this->f();$r=$this->proposal($f);A::review($f['checker'],1,$r,1,true,'Fictional review');AuditFault::install('centre_access_fault','portal_operations_events','fictional fault','centre_access_activated');try{A::apply($f['admin'],1,$r->fresh(),2);$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('centre_manager_grants',0);$this->assertSame('Approved',$r->fresh()->state);}
 public function test_revoke_audit_failure_keeps_exact_previous_grant():void {$f=$this->f();$g=$this->granted($f);AuditFault::install('centre_revoke_fault','portal_operations_events','fictional fault','centre_access_revoked');try{A::revoke($f['admin'],1,$f['manager'],$g->version,'Fictional revoke');$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertTrue(A::workspace($f['manager']));$this->assertSame($g->details_hash,$g->fresh()->details_hash);}
 public function test_empty_duplicate_overlarge_or_coordination_only_scope_is_refused():void {$f=$this->f();foreach([[[],['training']],[[$f['group']->id,$f['group']->id],['training']],[[$f['group']->id],['coordination']],[[$f['group']->id],['unknown']]]as[$groups,$areas]){$this->reject(fn()=>A::preview($f['admin'],$f['manager'],$groups,$areas,today()->addDays(10)->toDateString(),false));}}
 public function test_inactive_target_admin_target_and_expiry_outside_policy_are_refused():void {$f=$this->f();$f['manager']->forceFill(['active'=>false])->save();$this->reject(fn()=>$this->proposal($f));$this->reject(fn()=>A::preview($f['admin'],$f['checker'],[$f['group']->id],['training'],today()->addDays(10)->toDateString(),false));$f['manager']->forceFill(['active'=>true])->save();$this->reject(fn()=>A::preview($f['admin'],$f['manager'],[$f['group']->id],['training'],today()->addDays(366)->toDateString(),false));}
 public function test_delegated_scope_does_not_open_private_administration_or_historical_reports():void {$f=$this->f();$this->granted($f,['training','attendance','reviews','functional_skills','coordination']);$this->actingAs($f['manager']);foreach(['/centre-access','/privacy-administration','/reports/historical-cohorts','/account-operations','/staff-support-permissions']as$url){$this->get($url)->assertForbidden();}$this->assertFalse(LearningAccess::manager($f['manager']));}
 public function test_access_pages_render_clear_stages_and_private_headers():void {$f=$this->f();$r=$this->proposal($f);$this->actingAs($f['admin'])->get('/centre-access')->assertOk()->assertSee('1. Define an access proposal')->assertHeader('Referrer-Policy','no-referrer');$this->get('/centre-access/requests/'.$r->id)->assertOk()->assertSee('2. Review the exact access proposal');}
 public function test_delegation_never_changes_existing_tutor_training_or_signing_permissions():void {$f=$this->f();$before=$f['manager']->fresh()->getAttributes();$this->granted($f);$this->assertEquals($before,$f['manager']->fresh()->getAttributes());$this->assertFalse(LearningAccess::tutor($f['manager'],$f['a']));$this->assertFalse(\App\Support\SignedReviews::allowed($f['manager'],$f['a']));}
 public function test_authenticated_home_uses_existing_role_then_current_delegated_workspace():void {$f=$this->f();$this->actingAs($f['manager'])->get('/')->assertRedirect(route('staff.index'));$this->granted($f);$this->get('/')->assertRedirect(route('centre-oversight.index'));}
 public function test_unavailable_guest_home_intention_does_not_send_manager_back_to_apprentice_list():void {$f=$this->f();$this->actingAs($f['manager'])->withSession(['url.intended'=>route('apprentices.index')])->get('/')->assertRedirect(route('staff.index'));$this->assertNull(session('url.intended'));}
}
